func (c *_sortedCore) insert(n *_tnode, k, v any) (*_tnode, bool) {
	nativeEnter()
	defer nativeLeave()
	if n == nil {
		return &_tnode{e: &_mapEntry{key: k, val: v}, height: 1}, true
	}
	switch {
	case func() bool { nativeStep(); return c.less(k, n.e.key) }():
		l, added := func() (*_tnode, bool) { nativeStep(); return c.insert(n.left, k, v) }()

		return func() *_tnode { nativeStep(); return _tbalance(n.e, l, n.right) }(),

			added
	case func() bool { nativeStep(); return c.less(n.e.key, k) }():
		r, added := func() (*_tnode, bool) { nativeStep(); return c.insert(n.right, k, v) }()

		return func() *_tnode { nativeStep(); return _tbalance(n.e, n.left, r) }(),

			added
	}
	return func() *_tnode { nativeStep(); return _tmake(&_mapEntry{key: n.e.key, val: v}, n.left, n.right) }(),

		false
}

// delete removes a key that n has.
func (c *_sortedCore) delete(n *_tnode, k any) *_tnode {
	nativeEnter()
	defer nativeLeave()
	switch {
	case func() bool { nativeStep(); return c.less(k, n.e.key) }():
		return func() *_tnode {
			nativeStep()
			return _tbalance(n.e, func() *_tnode { nativeStep(); return c.delete(n.left, k) }(), n.right)
		}()

	case func() bool { nativeStep(); return c.less(n.e.key, k) }():
		return func() *_tnode {
			nativeStep()
			return _tbalance(n.e, n.left, func() *_tnode { nativeStep(); return c.delete(n.right, k) }())
		}()

	case n.left == nil:
		return n.right
	case n.right == nil:
		return n.left
	}

	m := n.right
	for m.left != nil {
		nativeStep()
		m = m.left
	}
	return func() *_tnode {
		nativeStep()
		return _tbalance(m.e, n.left, func() *_tnode { nativeStep(); return c.delete(n.right, m.e.key) }())
	}()

}

